/**
 * Materialized runtime environment for the mini program.
 *
 * GENERATED by `scripts/build-runtime.mjs` (`pnpm build:runtime [--environment
 * <name>] [--deployment-profile <name>]`). Committed with the development
 * defaults so DevTools compiles a fresh checkout without a prebuild step.
 *
 * Why a TypeScript module and not a JSON file: the WeChat dev-tool/compiler emits
 * `require("./runtime-env.json")` for a JSON import, and the mini-program module
 * system cannot resolve JSON modules — the whole app fails to boot with
 * "module 'runtime-env.json.js' is not defined". A `.ts` module compiles to a
 * normal module and loads on every base library.
 */
export interface SdkworkMallMpRuntimeEnvDocument {
  readonly commerceAppApiBaseUrl: string;
  readonly deploymentProfile: string;
  readonly environment: string;
}

/** Values injected at build time; `readRuntimeEnv` merges them with the channel. */
export const RUNTIME_ENV: SdkworkMallMpRuntimeEnvDocument = {
  commerceAppApiBaseUrl: "https://api-dev.sdkwork.com/app/v3/api",
  deploymentProfile: "standalone",
  environment: "development",
};
